18: import { inject, Injectable, signal } from '@angular/core';
19: import { AbstractControl, FormArray, FormGroup } from '@angular/forms';
20: import { FormlyFormBuilder } from '@ngx-formly/core';
21: import { FhirBedOccupancyService } from '../shared/services/fhir-bed-occupancy.service';
22: import { DeepMergeService } from '@gematik/demis-portal-core-library';
23: import { notifierFacilityBedOccupancyFormConfigFields } from '../shared/formly/configs/bed-occupancy/notifier-facility.config';
24: import { questionBedOccupancyHtmlConfigFieldsNew } from '../shared/formly/configs/bed-occupancy/question-new.config';
25: import { BedOccupancyFormModel, DeepPartial, NotifierFacilityFormModel } from '../shared/models/bed-occupancy-form-model';
26: import { BedOccupancyQuestion } from 'src/api/notification';
27: 
28: @Injectable({
29:   providedIn: 'root',
30: })
31: export class BedOccupancyNotificationService {
32:   private readonly fhirBedOccupancyService = inject(FhirBedOccupancyService);
33:   private readonly deepMergeService = inject(DeepMergeService);
34:   private readonly formlyBuilder = inject(FormlyFormBuilder);
35: 
36:   /**
37:    * FormGroups and models for each step.
38:    * The models are implemented as Signals for reactive updates.
39:    * The models are used by Formly to initialize the FormControls.
40:    *
41:    * Both FormGroups are pre-built via FormlyFormBuilder so that their
42:    * FormControls (and the real Formly validators) exist from the start,
43:    * even before the step is actually rendered. This makes `patchFormData`
44:    * and side-navigation validity indicators work correctly for every step
45:    * regardless of whether the user has visited it yet.
46:    *
47:    * The notifierFacility config is built with an empty hospital-locations
48:    * list initially; the concrete options are provided later by
49:    * NotifierFacilityComponent once the async HTTP call resolves. Formly's
50:    * `addControl` is idempotent, so re-rendering with the final config only
51:    * updates dynamic props (e.g. select options) without recreating controls.
52:    */
53:   notifierFacilityModel = signal<NotifierFacilityFormModel>({});
54:   bedOccupancyQuestionModel = signal<DeepPartial<BedOccupancyQuestion>>({});
55: 
56:   notifierFacilityGroup = new FormGroup({});
57:   bedOccupancyQuestionGroup = new FormGroup({});
58: 
59:   constructor() {
60:     // Eagerly build both FormGroups so their controls and Formly validators
61:     // are available before the corresponding step is rendered.
62:     this.formlyBuilder.buildForm(this.notifierFacilityGroup, notifierFacilityBedOccupancyFormConfigFields('', []), this.notifierFacilityModel(), {});
63:     this.formlyBuilder.buildForm(this.bedOccupancyQuestionGroup, questionBedOccupancyHtmlConfigFieldsNew(), this.bedOccupancyQuestionModel(), {});
64:   }
65: 
66:   sendData() {
67:     const model = this.getModelData();
68:     const transformedData = this.fhirBedOccupancyService.transformData(model);
69:     this.fhirBedOccupancyService.submitNotification(transformedData);
70:   }
71: 
72:   /**
73:    * Sets or updates form data for one or more steps by deep-merging the
74:    * provided partial data into the current model and the corresponding
75:    * FormGroup value.
76:    *
77:    * Because both FormGroups are pre-built in the constructor, the controls
78:    * always exist when this method runs and `patchValue` takes effect
79:    * immediately.
80:    *
81:    * Example:
82:    * ```
83:    * bedOccupancyNotificationService.patchFormData({
84:    *   notifierFacility: { name: 'Hospital XYZ' },
85:    *   bedOccupancyQuestion: { occupiedBeds: { adultsNumberOfBeds: 10 } }
86:    * });
87:    * ```
88:    */
89:   patchFormData(data: BedOccupancyFormModel, options: { markAsTouched?: boolean } = {}): void {
90:     const { markAsTouched = true } = options;
91:     const stepMappings = [
92:       { key: 'notifierFacility' as const, model: this.notifierFacilityModel, group: this.notifierFacilityGroup },
93:       { key: 'bedOccupancyQuestion' as const, model: this.bedOccupancyQuestionModel, group: this.bedOccupancyQuestionGroup },
94:     ];
95: 
96:     stepMappings.forEach(({ key, model, group }) => {
97:       if (!data[key]) return;
98: 
99:       const currentData = Object.keys(group.value).length > 0 ? group.value : model();
100:       const mergedData = this.deepMergeService.deepMerge(currentData, data[key]);
101: 
102:       model.set(mergedData);
103:       group.patchValue(mergedData);
104:       this.syncFormArrayLengths(group, mergedData);
105:       this.updateStepValidation(group, markAsTouched);
106:     });
107:   }
108: 
109:   /**
110:    * `FormGroup.patchValue` never adds or removes entries from a `FormArray`.
111:    * When merged data contains a shorter array than the current control
112:    * (typically because Formly seeded it with a `defaultValue: [{}]` empty
113:    * placeholder), the excess controls stay behind with their required inner
114:    * validators and keep the FormGroup invalid. This walks the control tree
115:    * and truncates each FormArray to match the merged data length.
116:    */
117:   private syncFormArrayLengths(control: AbstractControl, data: unknown): void {
118:     if (control instanceof FormArray) {
119:       const dataArray = Array.isArray(data) ? data : [];
120:       while (control.length > dataArray.length) {
121:         control.removeAt(control.length - 1);
122:       }
123:       control.controls.forEach((child, index) => this.syncFormArrayLengths(child, dataArray[index]));
124:       return;
125:     }
126:     if (control instanceof FormGroup) {
127:       const dataObject = data && typeof data === 'object' ? (data as Record<string, unknown>) : {};
128:       Object.keys(control.controls).forEach(key => this.syncFormArrayLengths(control.controls[key], dataObject[key]));
129:     }
130:   }
131: 
132:   /**
133:    * Helper method to trigger validation updates and statusChanges emission.
134:    *
135:    * When `markAsTouched` is false the FormGroup is explicitly reset to
136:    * `untouched`. `patchValue`, `FormArray.removeAt` and the FormlyForm's
137:    * initial rendering can otherwise leave residual touched state behind
138:    * (e.g. from a previous visit whose leaving triggered `markAllAsTouched`
139:    * in the process stepper). Untouching here guarantees that after a
140:    * programmatic prefill the side navigation shows the step number and
141:    * not a completed/error indicator until the user actually interacts.
142:    */
143:   private updateStepValidation(group: FormGroup, markAsTouched: boolean): void {
144:     if (markAsTouched) {
145:       group.markAllAsTouched();
146:     } else {
147:       group.markAsUntouched();
148:     }
149:     group.updateValueAndValidity({ emitEvent: true });
150:   }
151: 
152:   /**
153:    * Returns the current form data as a plain JavaScript object.
154:    * Uses the FormGroup values (as they contain the current values from the forms).
155:    */
156:   getFormData(): BedOccupancyFormModel {
157:     return {
158:       notifierFacility: this.notifierFacilityGroup.value,
159:       bedOccupancyQuestion: this.bedOccupancyQuestionGroup.value,
160:     };
161:   }
162: 
163:   /**
164:    * Returns the current model data as a plain JavaScript object.
165:    * Uses the Signal values (Models).
166:    */
167:   getModelData() {
168:     return {
169:       notifierFacility: this.notifierFacilityModel(),
170:       bedOccupancyQuestion: this.bedOccupancyQuestionModel(),
171:     };
172:   }
173: 
174:   /**
175:    * Checks if all FormGroups are valid and contain data.
176:    */
177:   isFormValid(): boolean {
178:     return this.notifierFacilityGroup.valid && this.bedOccupancyQuestionGroup.valid;
179:   }
180: 
181:   /**
182:    * Clears the touched state of both FormGroups. Should be called when the
183:    * entire wizard route is entered so a fresh visit does not carry over
184:    * validation state from a previous run within the same session.
185:    */
186:   resetVisitedFlags(): void {
187:     this.notifierFacilityGroup.markAsUntouched();
188:     this.bedOccupancyQuestionGroup.markAsUntouched();
189:   }
190: }

