18: import { Injectable } from '@angular/core';
19: import { ContactPointInfo } from 'src/api/notification';
20: import { validateEmail, validatePhoneNo } from '../notification-form-validation-module';
21: import ContactTypeEnum = ContactPointInfo.ContactTypeEnum;
22: 
23: /****
24:  *
25:  * This service contains all the validation common to all types of notifications.
26:  * Only the validation specific to each type of notification should be implemented
27:  * in the services of these notifications
28:  *
29:  */
30: 
31: @Injectable({ providedIn: 'root' })
32: export class ValidateNotificationService {
33:   validatePhoneNumber(phoneNumber: string, required: boolean): boolean {
34:     return required ? !!phoneNumber && !validatePhoneNo(phoneNumber) : !phoneNumber || !validatePhoneNo(phoneNumber);
35:   }
36: 
37:   validateEmailAddress(email: string, required: boolean): boolean {
38:     return required ? !!email && !validateEmail(email) : !email || !validateEmail(email);
39:   }
40: 
41:   async phoneValidator(data: { contacts: ContactPointInfo[] }): Promise<boolean> {
42:     const contacts: ContactPointInfo[] = await this.handelAsyncData(data);
43: 
44:     for (const contact of contacts) {
45:       if (contact.contactType === ContactTypeEnum.Phone && !this.validatePhoneNumber(contact.value, true)) {
46:         return false;
47:       }
48:     }
49: 
50:     return true;
51:   }
52: 
53:   async emailValidator(data: { contacts: ContactPointInfo[] }): Promise<boolean> {
54:     const contacts: ContactPointInfo[] = await this.handelAsyncData(data);
55: 
56:     for (const contact of contacts) {
57:       if (contact.contactType === ContactTypeEnum.Email && !this.validateEmailAddress(contact.value, true)) {
58:         return false;
59:       }
60:     }
61: 
62:     return true;
63:   }
64: 
65:   private handelAsyncData(data: { contacts: ContactPointInfo[] }): Promise<ContactPointInfo[]> {
66:     return new Promise(function (resolve) {
67:       window.setTimeout(function () {
68:         resolve(data.contacts);
69:       });
70:     });
71:   }
72: }

